// The demo makes decisions on the engine clock before it can cross a card
// deadline. Render time is deliberately clamped, so it must not drive the bot.
function advanceRace(rawDt){
 if(!demo){race.update(document.hidden?0:rawDt);events();question();return;}
 let remaining=document.hidden?0:Math.max(0,rawDt);
 while(remaining>1e-9&&mode==='racing'&&race.active&&!paused){
  const step=Math.min(.05,remaining);remaining-=step;race.update(step);events();question();
  const delay=aquatic?1.15:botTurns<2?2.2:botTurns<6?.9:botTurns<9?2.7:1.05;
  if(mode==='racing'&&race.active&&race.ready&&race.questionElapsed>=delay-1e-8){botTurns++;answer(botTurns%6===0?ArcadeNumberEntry.wrong(race.question.answer):race.question.answer);}
 }
}
function loop(now){if(practiceStopped)paused=true;const rawDt=Math.max(0,(now-frame)/1000),dt=Math.min(.1,rawDt),presentationDt=Math.min(.25,rawDt);frame=now;if(!paused){time+=dt;if(mode==='countdown'){count-=rawDt;if(count<=0){mode='racing';botAt=time;race.revealQuestion();question();note('OFF THE LINE!')}}else if(mode==='racing'){round?.tick(rawDt,true);advanceRace(rawDt)}else if(mode==='finish'){finishAt+=demo?rawDt:dt;if(race.won&&!race.timed){race.playerDistance+=(race.laps-race.playerDistance)*(1-Math.exp(-dt*2.5));race.paceDistance=Math.min(race.laps-.08,race.paceDistance+dt*race.paceSpeed)}if(finishAt>2.6){mode='results';paused=true;$('finish').showModal();if(!demo)post({type:'arcade-complete',won:race.won,correct:race.correct,attempts:race.attempts})}}responseMomentum*=Math.exp(-presentationDt*1.7);const honestGap=race?.gap||0;visualGap+=(honestGap+responseMomentum-visualGap)*(1-Math.exp(-presentationDt*6));const speed=(mode==='racing'||mode==='finish')?aquatic?65+(race?.speed||0)*650:Math.min(190,88+Math.tanh(visualGap/5)*18+(race?.boost>0?28:0)):0;displaySpeed+=(speed-displaySpeed)*(1-Math.exp(-dt*3));if(mode==='racing'||mode==='finish'){travel+=dt*(aquatic?Math.max(.08,race?.speed||.08)*3*(race?.boost>0?1.45:1):Math.max(.05,displaySpeed/100)*.9);if(aquatic){bridgePhase+=dt*(.095+Math.min(.08,(race?.speed||0)*.7))*(race?.boost>0?1.4:1);if(bridgePhase>1.23)bridgePhase-=1.23;}const desired=Math.sin(travel*.95)*.7;turn+=(desired-turn)*(1-Math.exp(-dt*1.8))}flash=Math.max(0,flash-dt);if(time>bannerUntil&&mode==='racing')$('banner').textContent=(race.boost>0?(aquatic?'🌊 HYDRO BOOST':'⚡ NITRO BURST'):Math.abs(race.gap)<.18?'SIDE BY SIDE • KEEP YOUR RHYTHM':race.gap>0?'YOU’RE PULLING AHEAD':(aquatic?'CHASE THE GOLD RIDER':'CHASE THE GOLD CAR'))}ui();draw(dt);requestAnimationFrame(loop)}
$('start').onclick=()=>start(false);$('demo').onclick=()=>start(true);$('again').onclick=()=>start(false);$('newSettings').onclick=()=>{$('finish').close();$('resume').hidden=true;$('setup').showModal()};$('settings').onclick=()=>{setRacePaused(true);$('resume').hidden=!(race?.active||mode==='finish');$('setup').showModal()};$('resume').onclick=()=>{$('setup').close();setRacePaused(practiceStopped)};$('pause').onclick=()=>{if(race?.active||mode==='finish')setRacePaused(!paused)};$('setup').addEventListener('cancel',e=>{if(!race)e.preventDefault();else if(race.active||mode==='finish')setRacePaused(practiceStopped)});document.addEventListener('visibilitychange',()=>{if(document.hidden)setRacePaused(true)});window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==parent)return;const d=e.data;if(d?.type==='arcade-wallet'&&Number.isFinite(d.coins)){wallet=d.coins;ui()}if(d?.type==='arcade-gear'){gear=d.gear||d;ui()}if(d?.type==='arcade-pause'){if(race?.active&&!paused)setRacePaused(true);return}if(d?.type!=='arcade-command')return;if(d.gear)gear=d.gear;if(d.action==='demo')start(true);else{setRacePaused(true);$('resume').hidden=!(race?.active||mode==='finish');$('finish').close();if(!$('setup').open)$('setup').showModal()}ui()});$('finish').addEventListener('close',()=>{if(mode==='results'&&!$('setup').open){$('resume').hidden=true;$('setup').showModal()}});post({type:'arcade-ready'});resize();ui();$('setup').showModal();requestAnimationFrame(loop);
